187	            Ok(match (lhs, rhs) {
188	                (lhs, rhs) if lhs == rhs => lhs,
189	                (Type::Any, _) | (_, Type::Any) => Type::Any,
190	                // (int, int) and (float, float) cases are already handled by the first match arm
191	                (
192	                    Type::Int | Type::Float | Type::Number,
193	                    Type::Int | Type::Float | Type::Number,
194	                ) => Type::Number,
195	
196	                (Type::Glob, Type::String) | (Type::String, Type::Glob) => Type::String,
197	                (Type::Record(this), Type::Record(that)) => {
198	                    Type::Record(widen_collection(this, that))
199	                }
200	                (Type::Table(this), Type::Table(that)) => Type::Table(widen_collection(this, that)),
201	                (Type::List(list_item), Type::Table(table))
202	                | (Type::Table(table), Type::List(list_item)) => {
